<?php get_header(); ?><main id="main" class="inner-page"><div class="container"><h1 class="page-display"><?php echo esc_html(is_archive() ? post_type_archive_title('', false) : 'Материалы'); ?><span class="heading-point">.</span></h1><?php if(have_posts()):?><div class="post-list"><?php while(have_posts()):the_post();?><article><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),22)); ?></p></article><?php endwhile;?></div><?php the_posts_pagination();?><?php else:?><p>Здесь пока нет опубликованных материалов.</p><?php endif;?></div></main><?php get_footer(); ?>
